insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000402', 'stories', 'published', '{"title":"Stories","seoTitle":"Stories — Ever After Memoir","seoDescription":"Wedding stories by Ever After Memoir — candid moments, quiet details and little films.","sections":[{"key":"intro","type":"page_intro","visible":true,"layout":"side","eyebrow":"Our stories","headline":"Every wedding\n*feels different.*","body":"Some are loud and golden, some are quiet and close. Here are a few, told the way they felt.","media":{"id":"00000000-0000-4000-8000-000000000006","url":"/brand/couple-standing.jpg","type":"image","alt":"Newlyweds standing together and smiling","width":441,"height":1088,"poster":null,"isSample":false}},{"key":"grid","type":"stories_grid","visible":true,"showFilters":true},{"key":"cta","type":"cta","visible":true,"headline":"Your story\n*could be next.*","body":"See which dates are still open.","link":{"label":"Check your date","href":"/contact#book"}}]}'::jsonb, '{"title":"Stories","seoTitle":"Stories — Ever After Memoir","seoDescription":"Wedding stories by Ever After Memoir — candid moments, quiet details and little films.","sections":[{"key":"intro","type":"page_intro","visible":true,"layout":"side","eyebrow":"Our stories","headline":"Every wedding\n*feels different.*","body":"Some are loud and golden, some are quiet and close. Here are a few, told the way they felt.","media":{"id":"00000000-0000-4000-8000-000000000006","url":"/brand/couple-standing.jpg","type":"image","alt":"Newlyweds standing together and smiling","width":441,"height":1088,"poster":null,"isSample":false}},{"key":"grid","type":"stories_grid","visible":true,"showFilters":true},{"key":"cta","type":"cta","visible":true,"headline":"Your story\n*could be next.*","body":"See which dates are still open.","link":{"label":"Check your date","href":"/contact#book"}}]}'::jsonb, now(), 1) on conflict (slug) do nothing;
insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000403', 'services', 'published', '{"title":"Services","seoTitle":"Services — Ever After Memoir","seoDescription":"Wedding day content, highlight films and personalised coverage by Ever After Memoir.","sections":[{"key":"intro","type":"page_intro","visible":true,"layout":"side","eyebrow":"Services","headline":"Made around\n*your day.*","body":"Every couple remembers different things. Choose what matters most to you, and we will shape the coverage around it.","media":{"id":"00000000-0000-4000-8000-000000000002","url":"/brand/rings-henna.jpg","type":"image","alt":"The couple’s hands with wedding rings and floral henna","width":1169,"height":1215,"poster":null,"isSample":false}},{"key":"list","type":"services_list","visible":true,"addonsHeadline":"Little extras","footnote":"Every wedding is different, so every quote is too. Pick your date and we will reply with options for your day."},{"key":"cta","type":"cta","visible":true,"headline":"Not sure what\n*you need?*","body":"Tell us about your day and we''ll help you choose.","link":{"label":"Check your date","href":"/contact#book"}}]}'::jsonb, '{"title":"Services","seoTitle":"Services — Ever After Memoir","seoDescription":"Wedding day content, highlight films and personalised coverage by Ever After Memoir.","sections":[{"key":"intro","type":"page_intro","visible":true,"layout":"side","eyebrow":"Services","headline":"Made around\n*your day.*","body":"Every couple remembers different things. Choose what matters most to you, and we will shape the coverage around it.","media":{"id":"00000000-0000-4000-8000-000000000002","url":"/brand/rings-henna.jpg","type":"image","alt":"The couple’s hands with wedding rings and floral henna","width":1169,"height":1215,"poster":null,"isSample":false}},{"key":"list","type":"services_list","visible":true,"addonsHeadline":"Little extras","footnote":"Every wedding is different, so every quote is too. Pick your date and we will reply with options for your day."},{"key":"cta","type":"cta","visible":true,"headline":"Not sure what\n*you need?*","body":"Tell us about your day and we''ll help you choose.","link":{"label":"Check your date","href":"/contact#book"}}]}'::jsonb, now(), 2) on conflict (slug) do nothing;
insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000404', 'about', 'published', '{"title":"About","seoTitle":"About — Ever After Memoir","seoDescription":"Ever After Memoir was created for the moments that deserve to be remembered beyond the photographs.","sections":[{"key":"intro","type":"page_intro","visible":true,"layout":"side","eyebrow":"About","headline":"Behind every memoir,\n*a thousand little feelings.*","body":"Ever After Memoir was created for the moments that deserve to be remembered beyond the photographs — the laughter, the happy tears, the quiet glances, and all the beautiful in-between.","media":{"id":"00000000-0000-4000-8000-000000000005","url":"/brand/bride-smile.jpg","type":"image","alt":"Bride in a tiara and veil smiling","width":462,"height":1089,"poster":null,"isSample":false}},{"key":"approach","type":"text_image","visible":true,"eyebrow":"How we work","headline":"Close enough to feel it.\n*Quiet enough to miss nothing.*","body":"We stay near the moments that matter and out of the way of the ones that should simply happen.\n\nThe result is content that feels like being there again — the getting ready, the vows, the people you love, and everything in between.","media":{"id":"00000000-0000-4000-8000-000000000007","url":"/brand/salam-closeup.jpg","type":"image","alt":"Bride kissing the groom’s hand, eyes closed","width":424,"height":532,"poster":null,"isSample":false},"imageSide":"right"},{"key":"founder","type":"founder","visible":false,"eyebrow":"The person behind the camera","headline":"Hello, *I am…*","name":"","role":"","body":"","media":null},{"key":"quote","type":"quote","visible":true,"text":"Your day, as it felt — not just as it looked."},{"key":"cta","type":"cta","visible":true,"headline":"Let''s keep your\n*memories close.*","body":"We would love to hear about your day.","link":{"label":"Check your date","href":"/contact#book"}}]}'::jsonb, '{"title":"About","