insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000405', 'contact', 'published', '{"title":"Contact","seoTitle":"Book your date — Ever After Memoir","seoDescription":"Check which wedding dates are still available with Ever After Memoir, then book on WhatsApp.","sections":[{"key":"book","type":"booking","visible":true,"eyebrow":"Book your date","headline":"Is your date\n*still free?*","body":"Pick your wedding date to see if we’re available. Tell us a little about your day, then we’ll continue the conversation on WhatsApp.","note":"Dates marked “Few slots left” already have another booking. Your date is confirmed once we reply."},{"key":"inquiry","type":"inquiry","visible":true,"headline":"Prefer email?\n*Send a detailed inquiry.*","body":"Tell us a little about your day, your plans, and the moments you want to remember most.","successHeadline":"Thank you — *we have your message.*","successBody":"We read every inquiry personally and will reply to the email you gave us.","privacyNote":"We only use these details to reply to your inquiry and plan your coverage. We never sell or share them."}]}'::jsonb, '{"title":"Contact","seoTitle":"Book your date — Ever After Memoir","seoDescription":"Check which wedding dates are still available with Ever After Memoir, then book on WhatsApp.","sections":[{"key":"book","type":"booking","visible":true,"eyebrow":"Book your date","headline":"Is your date\n*still free?*","body":"Pick your wedding date to see if we’re available. Tell us a little about your day, then we’ll continue the conversation on WhatsApp.","note":"Dates marked “Few slots left” already have another booking. Your date is confirmed once we reply."},{"key":"inquiry","type":"inquiry","visible":true,"headline":"Prefer email?\n*Send a detailed inquiry.*","body":"Tell us a little about your day, your plans, and the moments you want to remember most.","successHeadline":"Thank you — *we have your message.*","successBody":"We read every inquiry personally and will reply to the email you gave us.","privacyNote":"We only use these details to reply to your inquiry and plan your coverage. We never sell or share them."}]}'::jsonb, now(), 4) on conflict (slug) do nothing;
insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000406', 'privacy', 'published', '{"title":"Privacy","seoTitle":"Privacy policy — Ever After Memoir","seoDescription":"How Ever After Memoir handles the personal details you share with us.","sections":[{"key":"policy","type":"rich_text","visible":true,"headline":"Privacy policy","body":"## What we collect\n\nWhen you book a date or send an inquiry, we receive the details you type in: your name, your partner’s name, email, WhatsApp number, wedding date, location, the type of celebration, the service you are interested in, an optional budget and any notes.\n\n## Why we collect it\n\nWe use these details only to reply to you, prepare a quote and plan coverage for your wedding. When you book through WhatsApp, the conversation continues in WhatsApp under its own privacy terms.\n\n## Who can see it\n\nYour inquiry is stored securely and is only visible to the Ever After Memoir team. We do not sell, rent or share your details with anyone for marketing.\n\n## How long we keep it\n\nWe keep inquiries for as long as we need them to work with you, and delete closed inquiries we no longer need.\n\n## Your choices\n\nYou can ask us at any time to see, correct or delete the details you sent. Reply to any message from us or send a new inquiry with your request.\n\n## Cookies\n\nThis website does not use advertising or tracking cookies."}]}'::jsonb, '{"title":"Privacy","seoTitle":"Privacy policy — Ever After Memoir","seoDescription":"How Ever After Memoir handles the personal details you share with us.","sections":[{"key":"policy","type":"rich_text","visible":true,"headline":"Privacy policy","body":"## What we collect\n\nWhen you book a date or send an inquiry, we receive the details you type in: your name, your partner’s name, email, WhatsApp number, wedding date, location, the type of celebration, the service you are interested in, an optional budget and any notes.\n\n## Why we collect it\n\nWe use these details only to reply to you, prepare a quote and plan coverage for your wedding. When you book through WhatsApp, the conversation continues in WhatsApp under its own privacy terms.\n\n## Who can see it\n\nYour inquiry is stored securely and is only visible to the Ever After Memoir team. We do not sell, rent or share your details with anyone for marketing.\n\n## How long we keep it\n\nWe keep inquiries for as long as we need them to work with you, and delete closed inquiries we no longer need.\n\n## Your choices\n\nYou can ask us at any time to see, correct or delete the details you sent. Reply to any message from us or send a new inquiry with your request.\n\n## Cookies\n\nThis website does not use advertising or tracking cookies."}]}'::jsonb, now(), 5) on conflict (slug) do nothing;
insert into public.site_settings (id, status, draft, published, published_at) values ('00000000-0000-4000-8000-000000000901', 'published', '{"siteTitle":"Ever After Memoir","tagline":"Your day, as it felt.","metaDescription":"Ever After Memoir is a wedding content creator capturing honest moments, fleeting details and the beautiful in-between — in photographs, reels and little films.","logo":null,"favicon":null,"ogImage":{"id":"00000000-0000-4000-8000-000000000015","url":"/brand/og.jpg","type":"image","alt":"Ever After Memoir","width":1200,"height":630,"poster":null,"isSample":false},"contactEmail":"","whatsappNumber":"","whatsappMessage":"Hi Ever After Memoir, I''d love to ask about my wedding.","instagramUrl":"https://www.instagram.com/everafter.memoir/","tiktokUrl":"https://www.tiktok.com/@everafter.memoir/","footerNote":"Wedding content and little films, made for remembering.","filmGrain":true,"introAnimation":true,"celebrationTypes":["Solemnisation (akad nikah)","Reception (bersanding)","Solemnisation and reception","Engagement (tunang)","Something else"],"budgetRanges":[],"inquiryRetentionMonths":0,"bookingEnabled":true,"bookingLeadDays":7,"bookingMonthsAhead":18,"bookingMessage":"Hai Ever After Memoir! Saya nak tempah tarikh {date}.\n\nNama: {name}\nPasangan: {partner}\nMajlis: {type}\nServis: {service}\nLokasi: {location}\nNota: {notes}\n\nRujukan: {ref}"}'::jsonb, '{"siteTitle":"Ever After Memoir","tagline":"Your day, as it felt.","metaDescription":"Ever After Memoir is a wedding content creator capturing honest moments, fleeting details and the beautiful in-between — in photographs, reels and little films.","logo":null,"favicon":null,"ogImage":{"id":"00000000-0000-4000-8000-000000000015","url":"/brand/og.jpg","type":"image","alt":"Ever After Memoir","width":1200,"height":630,"poster":null,"isSample":false},"contactEmail":"","whatsappNumber":"","whatsappMessage":"Hi Ever After Memoir, I''d love to ask about my wedding.","instagramUrl":"https://www.instagram